  const limits = [...usageLimits].sort((a, b) => a - b);
  let total = 0;
  let groups = 0;

  for (const limit of limits) {
    total += limit;
    const needed = (groups + 1) * (groups + 2) / 2;
    if (total >= needed) {
      groups++;
    }
  }
  return groups;
}

