function maxIncreasingGroups(usageLimits) {
  // Max flow: source -> number i (capacity min(limit, k)) -> group j (capacity 1) -> sink (capacity j).
  const n = usageLimits.length;
  const feasible = (k) => {
    const size = n + k + 2, source = n + k, sink = n + k + 1;
    const cap = Array.from({ length: size }, () => new Array(size).fill(0));
    for (let i = 0; i < n; i++) {
      cap[source][i] = Math.min(usageLimits[i], k);
      for (let j = 0; j < k; j++) cap[i][n + j] = 1;
    }
    for (let j = 0; j < k; j++) cap[n + j][sink] = j + 1;
    let flow = 0;
    for (;;) {
      const prev = new Array(size).fill(-1);
      prev[source] = source;
      const queue = [source];
      while (queue.length && prev[sink] === -1) {
        const u = queue.shift();
        for (let v = 0; v < size; v++) if (prev[v] === -1 && cap[u][v] > 0) { prev[v] = u; queue.push(v); }
      }
      if (prev[sink] === -1) break;
      let push = Infinity;
      for (let v = sink; v !== source; v = prev[v]) push = Math.min(push, cap[prev[v]][v]);
      for (let v = sink; v !== source; v = prev[v]) { cap[prev[v]][v] -= push; cap[v][prev[v]] += push; }
      flow += push;
    }
    return flow === k * (k + 1) / 2;
  };
  let best = 0;
  for (let k = 1; k <= n; k++) if (feasible(k)) best = k;
  return best;
}

